def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            objects.append((max(x for y, x in cells), cells, color))
    out = [[0] * w for _ in range(h)]
    # Slide each rigid object rightward until it meets the edge or a previously
    # settled object. Rightmost objects settle first, as in the demos.
    for _, cells, color in sorted(objects, key=lambda obj: obj[0], reverse=True):
        shift = 0
        while True:
            nxt = [(y, x + shift + 1) for y, x in cells]
            if any(x >= w or out[y][x] != 0 for y, x in nxt):
                break
            shift += 1
        for y, x in cells:
            out[y][x + shift] = color
    return out
